 'truck':'<path d="M3 17V5h11v12M14 9h4l3 4v4h-2M14 17H7"/><circle cx="5.5" cy="18" r="2.5"/><circle cx="16.5" cy="18" r="2.5"/>',
 'box':'<path d="m12 3 9 5v10l-9 5-9-5V8zM3 8l9 5 9-5M12 13v10M7.5 5.5l9 5V15"/>',
