 'layers':'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',
 'sparkles':'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',
 'arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>',
 'ruler':'<path d="m3 16 13-13 5 5L8 21zM12 7l3 3M8 11l3 3M4 15l3 3"/>',
 'focus':'<path d="M3 8V4a1 1 0 0 1 1-1h4m8 0h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4"/><circle cx="12" cy="12" r="3"/>',
 'maximize':'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5"/>',
 'mouse':'<rect x="6" y="2" width="12" height="20" rx="6"/><path d="M12 2v7"/>',
 'mouse-pointer':'<path d="m4 3 15 9-7 1-3 7z"/>',
